import sys
from itertools import islice


def main():
    inp = sys.stdin.buffer
    n = int(inp.readline())
    password = {}  # username -> password given at registration
    active = set()  # usernames currently logged in
    out = []
    write = sys.stdout.write
    for line in islice(inp, n):
        parts = line.split()
        op, name = parts[0], parts[1]
        if op == b"register":
            if name in password:
                out.append("Username already exists")
            else:
                password[name] = parts[2]
                out.append("Registered Successfully")
        elif op == b"login":
            # Fails for unknown users, wrong passwords and users already logged in.
            if name not in active and password.get(name) == parts[2]:
                active.add(name)
                out.append("Logged In Successfully")
            else:
                out.append("Login Unsuccessful")
        else:
            if name in active:
                active.discard(name)
                out.append("Logged Out Successfully")
            else:
                out.append("Logout Unsuccessful")
        if len(out) == 65536:
            out.append("")
            write("\n".join(out))
            out.clear()
    out.append("")
    write("\n".join(out))


main()

import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static int lastFirst, lastFourth; // first and fourth byte of the last token

    // Reads an alphanumeric token of length <= 10 as a nonzero bijective base-63 number.
    static long nextCode() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        long x = 0;
        int len = 0;
        lastFirst = c;
        lastFourth = 0;
        while (c > ' ') {
            if (len == 3) lastFourth = c;
            int v = c <= '9' ? c - '0' + 1 : c <= 'Z' ? c - 'A' + 37 : c - 'a' + 11;
            x = x * 63 + v;
            len++;
            c = readByte();
        }
        return x;
    }

    // ponytail: users live in an open-addressing table keyed by the encoded username (memory-light
    // stand-in for a String hash map); passwords are compared by their encoding.
    static long[] keys, passwords;
    static boolean[] active;
    static int mask;

    static int slot(long key) {
        long h = key * 0x9E3779B97F4A7C15L;
        int i = (int) (h ^ (h >>> 32)) & mask;
        while (keys[i] != 0 && keys[i] != key) i = (i + 1) & mask;
        return i;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readInt();
        int cap = Integer.highestOneBit(Math.max(2, n) * 2) * 2;
        keys = new long[cap];
        passwords = new long[cap];
        active = new boolean[cap];
        mask = cap - 1;
        byte[] registered = "Registered Successfully\n".getBytes(), exists = "Username already exists\n".getBytes();
        byte[] loggedIn = "Logged In Successfully\n".getBytes(), loginFail = "Login Unsuccessful\n".getBytes();
        byte[] loggedOut = "Logged Out Successfully\n".getBytes(), logoutFail = "Logout Unsuccessful\n".getBytes();
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        for (int i = 0; i < n; i++) {
            nextCode();
            int first = lastFirst, fourth = lastFourth;
            long name = nextCode();
            int s = slot(name);
            if (first == 'r') { // register
                long pass = nextCode();
                if (keys[s] != 0) {
                    out.write(exists);
                } else {
                    keys[s] = name;
                    passwords[s] = pass;
                    out.write(registered);
                }
            } else if (fourth == 'i') { // login: fails for unknown users, wrong passwords, users already in
                long pass = nextCode();
                if (keys[s] != 0 && !active[s] && passwords[s] == pass) {
                    active[s] = true;
                    out.write(loggedIn);
                } else {
                    out.write(loginFail);
                }
            } else { // logout
                if (keys[s] != 0 && active[s]) {
                    active[s] = false;
                    out.write(loggedOut);
                } else {
                    out.write(logoutFail);
                }
            }
        }
        out.flush();
    }

    static long readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        long x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

type account struct {
	password string
	active   bool
}

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	tok := make([]byte, 0, 64)
	next := func() []byte {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		tok = tok[:0]
		for err == nil && c > ' ' {
			tok = append(tok, c)
			c, err = reader.ReadByte()
		}
		return tok
	}
	n, _ := strconv.Atoi(string(next()))
	users := make(map[string]*account)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < n; i++ {
		op := string(next())
		name := string(next())
		switch op {
		case "register":
			pass := string(next())
			if _, ok := users[name]; ok {
				w.WriteString("Username already exists\n")
			} else {
				users[name] = &account{password: pass}
				w.WriteString("Registered Successfully\n")
			}
		case "login":
			// Fails for unknown users, wrong passwords and users already logged in.
			pass := next()
			if a, ok := users[name]; ok && !a.active && a.password == string(pass) {
				a.active = true
				w.WriteString("Logged In Successfully\n")
			} else {
				w.WriteString("Login Unsuccessful\n")
			}
		default: // logout
			if a, ok := users[name]; ok && a.active {
				a.active = false
				w.WriteString("Logged Out Successfully\n")
			} else {
				w.WriteString("Logout Unsuccessful\n")
			}
		}
	}
}
